# Production bitwise helpers: alignment, power-of-2 check, Fenwick LSB, submask loop
def align_up(n: int, align: int) -> int:
    assert align > 0 and (align & (align - 1)) == 0, "align must be power of 2"
    return (n + align - 1) & ~(align - 1)

def lowest_set_bit(x: int) -> int:
    return x & -x

def iter_submasks(mask: int):
    sub = mask
    while sub > 0:
        yield sub
        sub = (sub - 1) & mask
    yield 0

def invert_bits(x: int, width: int = 32) -> int:
    return (~x) & ((1 << width) - 1) # masks Python's infinite sign bits
```

```python
# 1. Held-Karp TSP starting at node 0: O(n^2 * 2^n)
def tsp_held_karp(dist: list[list[int]]) -> int:
    n = len(dist)
    INF = 10**15
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0
    for mask in range(1, 1 << n):
        if not (mask & 1): continue
        for u in range(n):
            if dp[mask][u] == INF: continue
            for v in range(1, n):
                if not (mask & (1 << v)):
                    nxt = mask | (1 << v)
                    dp[nxt][v] = min(dp[nxt][v], dp[mask][u] + dist[u][v])
    full = (1 << n) - 1
    return min(dp[full][u] + dist[u][0] for u in range(1, n))

# 2. Sum over Subsets (SOS) DP: O(n * 2^n)
def sos_dp(A: list[int], n: int) -> list[int]:
    F = A[:]
    for i in range(n):
        for mask in range(1 << n):
            if mask & (1 << i):
                F[mask] += F[mask ^ (1 << i)]
    return F
```

