```python
# Core Raft AppendEntries log-consistency & commit invariant (Python)
class RaftNode:
    def __init__(self):
        self.current_term = 0
        self.log: list[tuple[int, bytes]] = [] # (term, command)
        self.commit_index = -1

    def handle_append_entries(self, term: int, prev_idx: int, prev_term: int,
                              entries: list[tuple[int, bytes]], leader_commit: int) -> tuple[int, bool]:
        if term < self.current_term:
            return self.current_term, False # fence stale leader
        self.current_term = term
        if prev_idx >= 0:
            if prev_idx >= len(self.log) or self.log[prev_idx][0] != prev_term:
                return self.current_term, False # log divergence -> leader decrements nextIndex
        # Truncate conflicting suffix & append new entries (fsync before returning True!)
        self.log = self.log[:prev_idx + 1] + entries
        if leader_commit > self.commit_index:
            self.commit_index = min(leader_commit, len(self.log) - 1)
        return self.current_term, True
```

```java
// Consistent Hash Ring using TreeMap and virtual nodes (Java)
public final class ConsistentHashRing {
    private final NavigableMap<Long, String> ring = new TreeMap<>();
    private final int vnodesPerHost;

    public ConsistentHashRing(int vnodesPerHost) {
        this.vnodesPerHost = vnodesPerHost;
    }

    public void addHost(String host) {
        for (int i = 0; i < vnodesPerHost; i++) {
            ring.put(hash64(host + "#" + i), host);
        }
    }

    public List<String> getReplicas(String key, int rf) {
        if (ring.isEmpty()) return List.of();
        List<String> result = new ArrayList<>(rf);
        Set<String> seenHosts = new HashSet<>();
        long h = hash64(key);
        var tail = ring.tailMap(h, true).values().iterator();
        var head = ring.values().iterator();
        while (result.size() < rf && seenHosts.size() < ring.size()) {
            String host = tail.hasNext() ? tail.next() : (head.hasNext() ? head.next() : null);
            if (host == null) break;
            if (seenHosts.add(host)) result.add(host); // skip duplicate physical hosts
        }
        return result;
    }
}
