package pool

import (
	"context"
	"sync"
)

func RunWorkerPool[T any](ctx context.Context, workers int, jobs <-chan T, fn func(context.Context, T) error) {
	var wg sync.WaitGroup
	wg.Add(workers)
	for i := 0; i < workers; i++ {
		go func() {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case job, ok := <-jobs:
					if !ok {
						return
					}
					_ = fn(ctx, job)
				}
